{"packet_id":"D006-01","doc_id":"D006","jurisdiction":"Berkeley, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Measure BB amendments to Berkeley Rent Ordinance — rent increase limits and coverage","requirement":"Caps the Annual General Adjustment at 5%, expands Rent Ordinance coverage to many government-owned or subsidized units, allows rent-increase petitions only for completed capital improvements, and regulates utility charges for fully covered units.","key_value":"5% maximum AGA","coverage_conditions":"Fully covered: most multifamily pre-1980 units and certain single-family homes. Partially covered: post-1980 units, most single-family homes/condos, certain subsidized units. Exempt: owner-occupied shared kitchen/bath under conditions.","applicability":{"built_on_or_before":"1980","built_after":"1980","date_basis":"certificate_of_occupancy","min_units":null,"max_units":null,"owner_dependent":true,"other":"Coverage tiers: fully, partially, exempt; some subsidized units now covered."},"exemptions":"Units where tenant shares kitchen/bath with landlord are exempt only if landlord lived on the same property at tenancy start; units exempted from rent control by federal/state law or regulation.","penalty":"Rent Board may adopt fines for noncompliance with registration, including failure to report new tenancies timely; no fine system yet created.","effective_date":null,"citation":"Measure BB (Berkeley Rent Ordinance)","quoted_span":"The maximum AGA is 5%. This means that, if the formula in the Rent Ordinance results in an AGA that is greater than 5%, the AGA approved by the Board for that year can be no more than 5%.","interaction":"Federal or State law or regulation may exempt certain subsidized units from rent control.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D006-01","doc_id":"D006","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Measure BB amendments to Berkeley Rent Ordinance — just cause eviction","requirement":"Bars eviction for nonpayment below one month's Fair Market Rent, bars eviction for refusing to sign a substantially similar lease, narrows material lease breach evictions, adds eviction notice filing rules, and requires annual inflation adjustments to owner move-in relocation assistance.","key_value":"1 month's Fair Market Rent threshold","coverage_conditions":"Tenants in units fully or partially covered by the Rent Ordinance cannot be evicted without just cause.","applicability":{"built_on_or_before":"1980","built_after":"1980","date_basis":"certificate_of_occupancy","min_units":null,"max_units":null,"owner_dependent":true,"other":"Applies to fully or partially covered units; exempt units not covered."},"exemptions":"Units exempt from the Rent Ordinance, including owner-occupied shared kitchen/bath units under conditions, are not subject to just cause.","penalty":null,"effective_date":null,"citation":"Measure BB (Berkeley Rent Ordinance)","quoted_span":"Eviction for nonpayment of rent is no longer permitted for rental debt of less than one month’s Fair Market Rent for a unit of equivalent size.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
